{"operation":"run_python","code":"import math

def is_rational(x):
    if x == 0:
        return True
    val = (-1 - math.sqrt(5))**x
    # Check if it's close to an integer or simple fraction
    # Since it's in Q(sqrt(5)), it's rational iff the sqrt(5) part is 0
    # (a + b*sqrt(5)) is rational iff b == 0
    # We can compute (1+sqrt(5))^x = a + b*sqrt(5)
    # recurrence: a_{n+1} = a_n + 5*b_n, b_{n+1} = a_n + b_n
    a, b = 1, 0
    for _ in range(abs(x)):
        if x > 0:
            a, b = a + 5*b, a + b
        else:
            # inverse of a + b*sqrt(5) is (a - b*sqrt(5))/(a^2 - 5b^2)
            denom = a*a - 5*b*b
            a, b = a/denom, -b/denom
    return b == 0

print([x for x in range(-10, 11) if is_rational(x)])"}

