import numpy as np

def r1(theta):
    return 2 - np.cos(theta)

def r2(theta):
    return 3 * np.cos(theta)

def inner_r(theta):
    return min(r1(theta), r2(theta))

area, _ = integrate.quad(lambda th: 0.5 * inner_r(th)**2, -np.pi/2, np.pi/2)
print("Numerical area:", area)

exact_area = (9 * np.pi / 4) - 4 + 3 * np.sqrt(3)
print("Exact area:", exact_area)
"}
